<?php require 'config.php';$u=require_login();require_innovations();page_start('Calendar',$u);heading('MAKE SPACE FOR WHAT COMES NEXT','Your month of possibilities.','Plan your workshops. Dates and countdowns use Africa/Freetown time.');$month=(string)($_GET['month']??date('Y-m'));if(!preg_match('/^\d{4}-\d{2}$/',$month)||substr($month,0,4)<'2000'||substr($month,0,4)>'2100')$month=date('Y-m');$start=DateTimeImmutable::createFromFormat('!Y-m-d',$month.'-01');if(!$start||$start->format('Y-m')!==$month)$start=new DateTimeImmutable('first day of this month');$end=$start->modify('+1 month');$events=rows('SELECT e.*,(SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.id AND r.user_id=?) mine FROM events e WHERE e.starts_at>=? AND e.starts_at<? ORDER BY starts_at',[$u['id'],$start->format('Y-m-d'),$end->format('Y-m-d')]);$days=[];foreach($events as $event)$days[(int)date('j',strtotime($event['starts_at']))][]=$event; ?>
<section class="card"><div class="section-title"><a class="ghost" href="calendar.php?month=<?=$start->modify('-1 month')->format('Y-m')?>" aria-label="Previous month">←</a><h2><?=$start->format('F Y')?></h2><a class="ghost" href="calendar.php?month=<?=$end->format('Y-m')?>" aria-label="Next month">→</a></div><div class="workshop-calendar" role="list" aria-label="Workshop dates">
<?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $day)echo '<div class="calendar-label">'.$day.'</div>';for($n=1;$n<(int)$start->format('N');$n++)echo '<div class="calendar-empty" aria-hidden="true"></div>';for($n=1;$n<=(int)$start->format('t');$n++):?><div class="calendar-day <?=isset($days[$n])?'has-event':''?>" role="listitem"><strong><?=$n?></strong><?php foreach($days[$n]??[] as $event):?><a href="#event-<?=$event['id']?>" title="<?=e($event['title'])?>"><?=e($event['title'])?></a><?php endforeach;?></div><?php endfor;?></div></section>
<div class="grid"><?php foreach($events as $event):?><article class="card" id="event-<?=$event['id']?>"><span class="badge"><?=$event['mine']?'Your booking':'Community workshop'?></span><h2><?=e($event['title'])?></h2><p><?=e($event['location'])?> · <?=date('d M, H:i',strtotime($event['starts_at']))?></p><p class="countdown" data-countdown="<?=e(date('c',strtotime($event['starts_at'])))?>">Starts <?=e(date('d M Y H:i',strtotime($event['starts_at'])))?></p><a class="button secondary" href="events.php">View booking options →</a></article><?php endforeach;if(!$events)echo '<section class="card empty-state"><h2>A little breathing room.</h2><p>No workshops in this month. Browse another month or ask an organiser about upcoming sessions.</p></section>';?></div>
<?php page_end(); ?>